 const [query,setQuery]=useState(""),[source,setSource]=useState<"all"|SkillSource>("all"),[category,setCategory]=useState<"all"|SkillCategory>("all"),[expanded,setExpanded]=useState<string|null>(null);
 const [reviewed,setReviewed]=useState<SkillItem[]>([]),[catalogError,setCatalogError]=useState(''),[catalogRevision,setCatalogRevision]=useState(0);
