 const skills=[...reviewed,...privateSkills].filter(s=>(source==="all"||s.source===source)&&(category==="all"||s.category===category)&&(`${s.title} ${s.slug} ${s.description} ${skillCategories.find(c=>c.id===s.category)?.label||""}`).toLocaleLowerCase("fr").includes(query.trim().toLocaleLowerCase("fr")));
