function SidebarNavItem({label,icon:Icon,active,collapsed,onClick,badge}:{label:string;icon:LucideIcon;active:boolean;collapsed:boolean;onClick:()=>void;badge?:number}){return <button type="button" className={"nav-item sidebar-nav-item "+(active?"active":"")} aria-label={collapsed?(badge?`${label}, ${badge} missions en cours`:label):undefined} aria-current={active?"page":undefined} data-tooltip={collapsed?label:undefined} onClick={onClick}><Icon size={20} strokeWidth={1.6}/>{!collapsed&&<span>{label}</span>}{badge&&badge>0?(collapsed?<span className="mission-dot collapsed-dot" aria-hidden="true"/>:<span className="mission-badge"><i className="mission-live-dot" aria-hidden="true"/>{badge}</span>):null}</button>;}
function RecentChats({resources,currentId,loading,onOpen,onSeeAll,actions,busy}:{resources:Resource[];currentId?:string;loading:boolean;onOpen:(resource:Resource)=>void;onSeeAll:()=>void;actions:ConversationActions;busy:boolean}){
 const [showArchived,setShowArchived]=useState(false);
 const sortRecent=(items:Resource[])=>items.sort((a,b)=>new Date(b.updated_at).getTime()-new Date(a.updated_at).getTime());
 const visibleWithCurrent=(items:Resource[],limit:number)=>{
  if(items.length<=limit)return items;
  const visible=items.slice(0,limit);
  const current=items.find(item=>item.id===currentId);
  if(current&&!visible.some(item=>item.id===current.id))visible[visible.length-1]=current;
  return visible;
 };
 const conversations=resources.filter(resource=>resource.kind==="conversation"&&resource.status!=="deleted");
 const pinned=visibleWithCurrent(sortRecent(conversations.filter(resource=>!isConversationArchived(resource)&&isConversationPinned(resource))),3);
 const recent=visibleWithCurrent(sortRecent(conversations.filter(resource=>!isConversationArchived(resource)&&!isConversationPinned(resource))),4);
 const archived=visibleWithCurrent(sortRecent(conversations.filter(isConversationArchived)),3);
 const renderChat=(chat:Resource)=><ConversationContextMenu key={chat.id} conversation={chat} actions={actions} isBusy={busy&&currentId===chat.id}><button type="button" className={"recent-chat "+(currentId===chat.id?"selected":"")} aria-current={currentId===chat.id?"page":undefined} aria-label={`${chat.title}${isConversationPinned(chat)?", épinglée":""}${isConversationUnread(chat)?", non lue":""}${isConversationArchived(chat)?", archivée":""}`} title={chat.title} onClick={()=>onOpen(chat)}><span className="recent-chat-title">{chat.title}</span>{isConversationPinned(chat)&&<span className="recent-chat-pin" aria-hidden="true"><Pin size={12}/></span>}{isConversationUnread(chat)&&<span className="recent-chat-unread" aria-label="Non lue"/>}</button></ConversationContextMenu>;
 return <div className="recent-chats" aria-label="Discussions">
  {loading&&!resources.length?<span className="recent-state">Chargement…</span>:<>
   {pinned.length>0&&<section className="recent-chat-section" aria-label="Discussions épinglées"><h3 className="recent-chat-section-title">Épinglées</h3><div className="recent-chat-list">{pinned.map(renderChat)}</div></section>}
   <section className="recent-chat-section" aria-label="Discussions récentes"><h3 className="recent-chat-section-title">Récentes</h3>{recent.length?<div className="recent-chat-list">{recent.map(renderChat)}</div>:<span className="recent-state">Aucune discussion récente</span>}</section>
   {archived.length>0&&<section className="recent-chat-section recent-archived-section"><button type="button" className="recent-chat-section-title recent-archive-toggle" aria-expanded={showArchived} onClick={()=>setShowArchived(open=>!open)}><span>Archivées <span className="recent-archive-count">{conversations.filter(isConversationArchived).length}</span></span><ChevronRight size={13} className={showArchived?"expanded":""}/></button>{showArchived&&<div className="recent-chat-list">{archived.map(renderChat)}{conversations.filter(isConversationArchived).length>archived.length&&<button type="button" className="recent-see-all recent-archive-all" onClick={onSeeAll}>Voir toutes les archives<ChevronRight size={14}/></button>}</div>}</section>}
  </>}
  <button type="button" className="recent-see-all" onClick={onSeeAll}>Tout voir<ChevronRight size={14}/></button>
 </div>;
}
const homePlaceholderPhrases=["Décrivez votre idée, ou déposez un fichier…","Créez un visuel pour votre produit…","Transformez votre idée en page…","Trouvez vos prochains clients…"];
const chatPlaceholderPhrases=["Continuez votre échange avec Braand…","Décrivez ce que vous souhaitez ajuster…","Posez une question sur votre projet…"];
const subscribeReducedMotion=(onChange:()=>void)=>{const media=window.matchMedia("(prefers-reduced-motion: reduce)");media.addEventListener("change",onChange);return()=>media.removeEventListener("change",onChange);};
const getReducedMotion=()=>window.matchMedia("(prefers-reduced-motion: reduce)").matches;
function AnimatedPlaceholder({home}:{home:boolean}){
 const firstPhrase=home?homePlaceholderPhrases[0]:chatPlaceholderPhrases[0];
 const [displayed,setDisplayed]=useState(firstPhrase),reducedMotion=useSyncExternalStore(subscribeReducedMotion,getReducedMotion,()=>false);
 useEffect(()=>{
  if(reducedMotion)return;
  const phrases=home?homePlaceholderPhrases:chatPlaceholderPhrases;
  let phraseIndex=0,position=phrases[0].length,deleting=true,timer=0,cancelled=false;
  const tick=()=>{if(cancelled)return;if(deleting){position=Math.max(0,position-1);setDisplayed(phrases[phraseIndex].slice(0,position));if(position===0){deleting=false;phraseIndex=(phraseIndex+1)%phrases.length;timer=window.setTimeout(tick,260);return;}timer=window.setTimeout(tick,20);return;}const phrase=phrases[phraseIndex];position=Math.min(phrase.length,position+1);setDisplayed(phrase.slice(0,position));if(position===phrase.length){deleting=true;timer=window.setTimeout(tick,1900);return;}timer=window.setTimeout(tick,34);};
  timer=window.setTimeout(tick,2100);
  return()=>{cancelled=true;window.clearTimeout(timer);};
 },[reducedMotion,home]);
 return <span className="composer-placeholder" aria-hidden="true">{displayed}<span className="composer-placeholder-caret"/></span>;
}
